<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>InfraWatch</title><style>:root{--panel:#0e2035;--line:#24445f;--text:#e8f2fa;--muted:#91abc1;--blue:#38bdf8;--green:#34d399;--red:#fb7185;--amber:#fbbf24}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#071221,#0c1d31);color:var(--text);font:14px system-ui,sans-serif}.top{background:#09192b;border-bottom:1px solid var(--line);display:flex;gap:18px;align-items:center;padding:16px 4%}.brand{font-weight:900;font-size:18px}.brand b{color:var(--blue)}nav{display:flex;gap:7px;flex:1}nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:7px}nav a:hover{color:#fff;background:#17324d}.container{max-width:1380px;margin:auto;padding:30px 24px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.metric{font-size:31px;font-weight:800;margin-top:8px}.muted{color:var(--muted)}.stat{border-top:3px solid var(--blue)}.good{border-color:var(--green)}.bad{border-color:var(--red)}.warn{border-color:var(--amber)}.two{display:grid;grid-template-columns:1.3fr .7fr;gap:16px}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid #1c3953}th{color:#9dc2dd}.button{display:inline-flex;align-items:center;justify-content:center;background:#168bb9;color:#fff;border:0;border-radius:7px;padding:9px 13px;text-decoration:none;cursor:pointer;font:inherit;line-height:1.1}.button:hover{background:#249fd0}.badge{padding:4px 9px;border-radius:99px;font-size:12px;font-weight:700}.up{background:#0d3b31;color:#76edc6}.down{background:#4a1d2a;color:#ff9cac}.degraded{background:#4b3916;color:#fbd16c}.unknown{background:#24364b;color:#bbd0e3}.bar{height:10px;background:#09203a;border-radius:10px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,var(--blue),#a78bfa)}.row{display:grid;grid-template-columns:120px 1fr 40px;gap:10px;align-items:center;margin:14px 0}.table-actions{display:flex;gap:8px;align-items:center;white-space:nowrap}.table-actions form{margin:0}.edit-button{background:#1d5d83}.edit-button:hover{background:#287eae}.delete-button{background:#8f2d44}.delete-button:hover{background:#b83d59}.action-icon{font-size:16px;margin-right:5px}form.card{max-width:760px;padding:28px}form.card>label{display:block;margin:20px 0 8px;font-weight:600;color:#c9dced}form.card input:not([type=hidden]):not([type=checkbox]):not([type=radio]),form.card select,form.card textarea{display:block;width:100%;padding:12px 14px;color:#e8f2fa;background:#091725;border:1px solid #31516c;border-radius:8px;font:inherit;color-scheme:dark}form.card input:focus,form.card select:focus,form.card textarea:focus{outline:2px solid #38bdf8;outline-offset:2px}form.card textarea{min-height:110px}form.card>button{margin-top:22px}form.card input[type=checkbox],form.card input[type=radio]{width:auto;accent-color:#38bdf8}.frequency-options{display:flex;gap:12px;flex-wrap:wrap}.frequency-options label{padding:12px 18px;background:#132b43;border:1px solid #31516c;border-radius:8px;cursor:pointer}.time-row{display:flex;align-items:center;gap:12px;margin-bottom:12px}.time-row input{flex:1}[hidden]{display:none!important}@media(max-width:760px){.top{flex-wrap:wrap}.top nav{order:3;overflow:auto;flex-basis:100%}.container{padding:18px 12px}.two{grid-template-columns:1fr}.row{grid-template-columns:85px 1fr 30px}}</style></head><body><header class="top"><span class="brand">INFRA<b>WATCH</b></span><nav><a href="{{ route('dashboard') }}">Dashboard</a><a href="{{ route('devices.index') }}">Devices</a><a href="{{ route('sites.index') }}">Sites</a>@if(auth()->user()->hasAnyRole(['administrator']))<a href="{{ route('administrators.index') }}">Users</a><a href="{{ route('monitoring-schedules.index') }}">Schedules</a><a href="{{ route('monitoring-profiles.index') }}">Ping Profiles</a>@endif</nav><form method="POST" action="{{ route('logout') }}">@csrf<button class="button">Sign out</button></form></header><main class="container">@if(session('status'))<p class="card">{{ session('status') }}</p>@endif @if($errors->any())<div class="card">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif{{ $slot }}</main></body></html>
